{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/update_file","args":{"repository_full_name":"oldmangrizzz/The_Workshop_Mk1","path":"DOTTIE_BODY/src/memory.mjs","content":"import { createHash } from "node:crypto";

function safeId(value) {
  return (
    String(value)
      .replace(/[^A-Za-z0-9._-]+/g, "-")
      .replace(/^-+|-+$/g, "") || "event"
  );
}

function extractContext(result) {
  if (typeof result === "string") return { text: result, provenance: [] };
  if (!result || typeof result !== "object") return { text: "", provenance: [] };

  if (typeof result.rendered === "string") {
    return { text: result.rendered, provenance: result.entries ?? result.provenance ?? result.sources ?? [] };
  }
  if (typeof result.context === "string") {
    return { text: result.context, provenance: result.provenance ?? result.sources ?? [] };
  }
  if (typeof result.text === "string") {
    return { text: result.text, provenance: result.provenance ?? result.sources ?? [] };
  }
  if (typeof result.content === "string") {
    return { text: result.content, provenance: result.provenance ?? result.sources ?? [] };
  }

  const passages = Array.isArray(result.items)
    ? result.items
        .map((item) => item?.content ?? item?.text ?? item?.overview ?? "")
        .filter(Boolean)
        .join("\n\n")
    : "";
  return { text: passages, provenance: result.provenance ?? result.sources ?? result.items ?? [] };
}

export class DottieMemory {
  constructor({
    client,
    sessionId = "dottie",
    memoryRoot = "viking://~/memories",
    recallTokens = 3500,
  }) {
    if (!client) throw new TypeError("OpenViking client required");
    this.client = client;
    this.sessionId = sessionId;
    this.memoryRoot = memoryRoot.replace(/\/$/, "");
    this.recallTokens = recallTokens;
  }

  async ensureSession() {
    const exists = await this.client.sessionExists(this.sessionId);
    if (!exists) {
      await this.client.createSession({
        sessionId: this.sessionId,
        autoCommitPolicy: null,
      });
    }
  }

  async recall(query) {
    if (!String(query ?? "").trim()) return { text: "", provenance: [] };
    await this.ensureSession();
    const result = await this.client.searchContext(query, {
      sessionId: this.sessionId,
      includeProvenance: true,
      maxTokens: this.recallTokens,
      purpose: "chat",
      detail: "balanced",
    });
    return extractContext(result);
  }

  async commitEvent({ id, markdown, tags = [] }) {
    const uri = `${this.memoryRoot}/events/${safeId(id)}.md`;
    await this.client.write(uri, markdown, {
      wait: true,
      processingMode: "semantic_and_vectors",
      tags: ["agent=dottie", "kind=autobiographical-event", ...tags],
    });
    const readback = await this.client.read(uri, 0, -1);
    if (readback !== markdown) throw new Error(`OpenViking verification failed for ${uri}`);
    return {
      uri,
      verified: true,
      sha256: createHash("sha256").update(markdown).digest("hex"),
    };
  }
}
