{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/update_file","args":{"repository_full_name":"oldmangrizzz/The_Workshop_Mk1","path":"DOTTIE_BODY/test/memory.test.mjs","content":"import test from "node:test";
import assert from "node:assert/strict";
import { DottieMemory } from "../src/memory.mjs";

function fakeClient() {
  const files = new Map();
  return {
    files,
    created: 0,
    searches: [],
    async sessionExists() { return this.created > 0; },
    async createSession() { this.created += 1; return { session_id: "dottie" }; },
    async searchContext(query, options) {
      this.searches.push({ query, options });
      return { rendered: "remembered fact", entries: [{ uri: "viking://receipt" }] };
    },
    async write(uri, content) { files.set(uri, content); return {}; },
    async read(uri) { return files.get(uri); },
  };
}

test("OpenViking recall is scoped to Dottie's session", async () => {
  const client = fakeClient();
  const memory = new DottieMemory({ client });
  const recalled = await memory.recall("where were we");
  assert.equal(client.created, 1);
  assert.equal(client.searches[0].options.sessionId, "dottie");
  assert.equal(client.searches[0].options.purpose, "chat");
  assert.equal(recalled.text, "remembered fact");
  assert.equal(recalled.provenance[0].uri, "viking://receipt");
});

test("memory commit writes then verifies exact readback", async () => {
  const client = fakeClient();
  const memory = new DottieMemory({ client });
  const receipt = await memory.commitEvent({ id: "evt/1", markdown: "# event" });
  assert.equal(receipt.verified, true);
  assert.match(receipt.uri, /events\/evt-1\.md$/);
  assert.match(receipt.sha256, /^[0-9a-f]{64}$/);
});

test("memory commit fails if OpenViking readback differs", async () => {
  const client = fakeClient();
  client.read = async () => "different";
  const memory = new DottieMemory({ client });
  await assert.rejects(() => memory.commitEvent({ id: "evt", markdown: "expected" }), /verification failed/);
});
