{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/The_Workshop_Mk1","path":"DOTTIE_BODY/src/openviking-client.mjs","content":"export class OpenVikingHttpError extends Error {
  constructor(message, { status, code, details } = {}) {
    super(message);
    this.name = "OpenVikingHttpError";
    this.status = status;
    this.code = code;
    this.details = details;
  }
}

function compact(object) {
  return Object.fromEntries(
    Object.entries(object).filter(([, value]) => value !== undefined && value !== null),
  );
}

export class OpenVikingHttpClient {
  constructor({
    baseUrl = "http://127.0.0.1:1933",
    apiKey,
    account,
    user = "dottie",
    timeoutMs = 60_000,
    fetchImpl = globalThis.fetch,
  } = {}) {
    if (typeof fetchImpl !== "function") throw new TypeError("fetch implementation required");
    const parsed = new URL(baseUrl);
    if (!/^https?:$/.test(parsed.protocol)) throw new TypeError("OpenViking baseUrl must use http or https");
    this.baseUrl = baseUrl.replace(/\/+$/, "");
    this.timeoutMs = timeoutMs;
    this.fetch = fetchImpl;
    this.headers = new Headers();
    if (apiKey) this.headers.set("X-API-Key", apiKey);
    if (account) this.headers.set("X-OpenViking-Account", account);
    if (user) this.headers.set("X-OpenViking-User", user);
  }

  async request(method, path, { query, body, signal } = {}) {
    const url = new URL(`${this.baseUrl}${path.startsWith("/") ? path : `/${path}`}`);
    for (const [key, value] of Object.entries(query ?? {})) {
      if (value === undefined || value === null || value === "") continue;
      if (Array.isArray(value)) {
        for (const item of value) {
          if (item !== undefined && item !== null && item !== "") url.searchParams.append(key, String(item));
        }
      } else {
        url.searchParams.set(key, String(value));
      }
    }

    const headers = new Headers(this.headers);
    const controller = new AbortController();
    const forwardAbort = () => controller.abort(signal.reason);
    if (signal) {
      if (signal.aborted) controller.abort(signal.reason);
      else signal.addEventListener("abort", forwardAbort, { once: true });
    }
    const timer = setTimeout(
      () => controller.abort(new DOMException("Request timed out", "TimeoutError")),
      this.timeoutMs,
    );
    if (typeof timer.unref === "function") timer.unref();

    try {
      const init = { method, headers, signal: controller.signal };
      if (body !== undefined) {
        headers.set("Content-Type", "application/json");
        init.body = JSON.stringify(body);
      }
      const response = await this.fetch(url, init);
      const text = await response.text();
      let envelope = {};
      if (text) {
        try {
          envelope = JSON.parse(text);
        } catch (cause) {
          throw new OpenVikingHttpError(`HTTP ${response.status}: ${text.slice(0, 240)}`, {
            status: response.status,
            details: { cause: String(cause) },
          });
        }
      }
      if (!response.ok || envelope.status === "error" || envelope.error) {
        throw new OpenVikingHttpError(
          envelope?.error?.message ?? String(envelope?.detail ?? `HTTP ${response.status}`),
          {
            status: response.status,
            code: envelope?.error?.code,
            details: envelope?.error?.details,
          },
        );
      }
      return envelope.result;
    } finally {
      clearTimeout(timer);
      if (signal) signal.removeEventListener("abort", forwardAbort);
    }
  }

  async sessionExists(sessionId) {
    try {
      await this.request("GET", `/api/v1/sessions/${encodeURIComponent(sessionId)}`);
      return true;
    } catch (error) {
      if (error instanceof OpenVikingHttpError && error.status === 404) return false;
      throw error;
    }
  }

  createSession({ sessionId, autoCommitPolicy = null } = {}) {
    return this.request("POST", "/api/v1/sessions", {
      body: compact({
        session_id: sessionId,
        auto_commit_policy: autoCommitPolicy,
      }),
    });
  }

  searchContext(query, options = {}) {
    return this.request("POST", "/api/v1/search/search", {
      body: compact({
        query,
        mode: "context",
        search_type: options.searchType,
        session_id: options.sessionId,
        limit: options.limit,
        node_limit: options.nodeLimit,
        score_threshold: options.scoreThreshold,
        filter: options.filter,
        context_type: options.contextType,
        include_provenance: options.includeProvenance,
        tags: options.tags,
        since: options.since,
        until: options.until,
        time_field: options.timeField,
        events_time_decay_protection: options.eventsTimeDecayProtection,
        query_expansion: options.queryExpansion,
        max_tokens: options.maxTokens,
        quotas: options.quotas,
        purpose: options.purpose,
        detail: options.detail,
        dedup_turns: options.dedupTurns,
        exclude_uris: options.excludeUris,
        peer_scope: options.peerScope,
        other_peer_penalty: options.otherPeerPenalty,
        rewrite: options.rewrite,
        rewrite_max_bullets: options.rewriteMaxBullets,
      }),
    });
  }

  write(uri, content, options = {}) {
    return this.request("POST", "/api/v1/content/write", {
      body: compact({
        uri,
        content,
        mode: options.mode,
        processing_mode: options.processingMode,
        tags: options.tags,
        tag_mode: options.tagMode,
        wait: options.wait,
      }),
    });
  }

  read(uri, offset = 0, limit = -1) {
    return this.request("GET", "/api/v1/content/read", {
      query: { uri, offset, limit },
    });
  }
}
