{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/The_Workshop_Mk1","path":"DOTTIE_BODY/src/cli.mjs","content":"#!/usr/bin/env node
import process from "node:process";
import { builtinModels } from "@earendil-works/pi-ai/providers/all";
import { NodeExecutionEnv } from "@earendil-works/pi-durable/env/node";
import { CodingTools } from "@earendil-works/pi-durable/tools";
import { openDottieRuntime } from "./runtime.mjs";

const provider = process.env.DOTTIE_PROVIDER;
const modelId = process.env.DOTTIE_MODEL;
if (!provider || !modelId) {
  console.error("DOTTIE_PROVIDER and DOTTIE_MODEL are required.");
  process.exit(2);
}

const models = builtinModels();
const cwd = process.env.DOTTIE_CWD || process.cwd();
const storagePath = process.env.DOTTIE_STORAGE || "./dottie.sqlite";

const runtime = await openDottieRuntime({
  models,
  model: { provider, modelId },
  storagePath,
  extensions: [CodingTools],
  env: (target) => new NodeExecutionEnv({ cwd: target.cwd ?? cwd }),
  identity: { attribution: { name: "Dottie Hill / GMRI" } },
  onReport: (error, info) => {
    console.error("[dottie-report]", info?.type ?? "unknown", error instanceof Error ? error.message : error);
  },
});

const input = process.argv.slice(2).join(" ").trim();
if (!input) {
  console.error("Pass a message as command-line arguments.");
  await runtime.close();
  process.exit(2);
}

try {
  const { settled } = await runtime.submit(input, {
    sourceId: process.env.DOTTIE_SOURCE_ID || "operator:cli",
  });
  if (settled.status !== "done" || settled.type !== "input") {
    console.error(JSON.stringify(settled));
    process.exitCode = 1;
  } else {
    const message = settled.answer?.model?.[0];
    if (message?.role === "assistant") {
      const text = Array.isArray(message.content)
        ? message.content.filter((part) => part.type === "text").map((part) => part.text).join("\n")
        : String(message.content ?? "");
      process.stdout.write(text + "\n");
    } else {
      process.stdout.write(JSON.stringify(settled.answer) + "\n");
    }
  }
} finally {
  await runtime.close();
}
