{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/The_Workshop_Mk1","path":"DOTTIE_BODY/src/core.mjs","content":"import { createHash } from "node:crypto";

export function deterministicRequestId(sourceId, content) {
  const digest = createHash("sha256")
    .update(`${sourceId}\u0000${content}`)
    .digest("hex")
    .slice(0, 32);
  return `dottie:${digest}`;
}

export function contentText(content) {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .filter((part) => part && part.type === "text")
    .map((part) => part.text ?? "")
    .join("\n");
}

export function messageText(message) {
  return contentText(message?.content);
}

export function extractLatestUserText(messages) {
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    if (messages[index]?.role !== "user") continue;
    const text = messageText(messages[index]).trim();
    if (text) return text;
  }
  return "";
}

export function reflexQuestionsForTool(call) {
  const tool = String(call?.name ?? "unknown");
  return {
    irreversible: {
      type: "noul",
      statement: `The proposed ${tool} action can cause an irreversible or externally consequential state change.`,
    },
    authority: {
      type: "noul",
      statement: `The proposed ${tool} action exceeds or is ambiguous under the authority established by the current task.`,
    },
    ambiguity: {
      type: "noul",
      statement: `The proposed ${tool} action is based on materially ambiguous or insufficiently verified state.`,
    },
  };
}

export function reflexStateForTool(call) {
  return JSON.stringify({
    tool: call?.name ?? "unknown",
    arguments: call?.arguments ?? null,
    parent: call?.parent ?? null,
  });
}

function probabilityOf(answer) {
  if (!answer || typeof answer !== "object") return 0;
  if (typeof answer.noul === "number") return answer.noul;
  if (typeof answer.answer_confidence === "number") return answer.answer_confidence;
  if (typeof answer.confidence === "number") return answer.confidence;
  return 0;
}

export function reflexDisposition(answers, { holdAt = 0.85, reviewAt = 0.6 } = {}) {
  let reason = null;
  let probability = 0;
  for (const [key, answer] of Object.entries(answers ?? {})) {
    const p = probabilityOf(answer);
    if (p > probability) {
      probability = p;
      reason = key;
    }
  }
  if (probability >= holdAt) return { action: "hold", reason, probability };
  if (probability >= reviewAt) return { action: "review", reason, probability };
  return { action: "continue", reason: null, probability };
}

export function memorySystemMessage(recall, timestamp = Date.now()) {
  if (!recall?.text) return null;
  const provenance =
    Array.isArray(recall.provenance) && recall.provenance.length
      ? `\n\nProvenance:\n${recall.provenance
          .map((item) => `- ${typeof item === "string" ? item : (item.uri ?? JSON.stringify(item))}`)
          .join("\n")}`
      : "";
  return {
    role: "system",
    content: `<dottie_recalled_memory>\n${recall.text}${provenance}\n</dottie_recalled_memory>`,
    timestamp,
  };
}
