{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/The_Workshop_Mk1","path":"DOTTIE_BODY/src/laya-client.mjs","content":"export class LayaClient {
  constructor({
    baseUrl = "http://127.0.0.1:3777",
    systemOneUrl,
    apiKey,
    timeoutMs = 15_000,
    fetchImpl = globalThis.fetch,
  } = {}) {
    if (typeof fetchImpl !== "function") throw new TypeError("fetch implementation required");
    this.url = systemOneUrl ?? `${baseUrl.replace(/\/$/, "")}/v1/systemone`;
    this.apiKey = apiKey;
    this.timeoutMs = timeoutMs;
    this.fetch = fetchImpl;
  }

  async judge(state, questions, { signal } = {}) {
    const controller = new AbortController();
    const timer = setTimeout(
      () => controller.abort(new Error("System One timeout")),
      this.timeoutMs,
    );
    if (typeof timer.unref === "function") timer.unref();

    const forwardAbort = () => controller.abort(signal.reason);
    if (signal) {
      if (signal.aborted) controller.abort(signal.reason);
      else signal.addEventListener("abort", forwardAbort, { once: true });
    }

    try {
      const headers = { "content-type": "application/json" };
      if (this.apiKey) headers.authorization = `Bearer ${this.apiKey}`;
      const response = await this.fetch(this.url, {
        method: "POST",
        headers,
        body: JSON.stringify({ state, questions }),
        signal: controller.signal,
      });
      const raw = await response.text();
      if (!response.ok) throw new Error(`System One ${response.status}: ${raw.slice(0, 240)}`);
      const payload = JSON.parse(raw || "{}");
      if (!payload || typeof payload !== "object" || !payload.answers || typeof payload.answers !== "object") {
        throw new Error("System One response has no answers map");
      }
      return payload;
    } finally {
      clearTimeout(timer);
      if (signal) signal.removeEventListener("abort", forwardAbort);
    }
  }
}

