{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/The_Workshop_Mk1","path":"DOTTIE_BODY/src/pi-extension.mjs","content":"import {
  GenerationTask,
  ToolTask,
  defineExtension,
  hook,
} from "@earendil-works/pi-durable";
import {
  extractLatestUserText,
  memorySystemMessage,
  messageText,
  reflexDisposition,
  reflexQuestionsForTool,
  reflexStateForTool,
} from "./core.mjs";

function injectBeforeLatestUser(messages, injected) {
  if (!injected) return messages;
  let index = messages.length;
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    if (messages[i]?.role === "user") {
      index = i;
      break;
    }
  }
  return [...messages.slice(0, index), injected, ...messages.slice(index)];
}

function eventMarkdown(message, taskId, observedAt) {
  const text = messageText(message).trim();
  return [
    "# Dottie experience",
    "",
    `Pi task: ${taskId}`,
    `Observed: ${new Date(observedAt).toISOString()}`,
    "",
    text,
  ].join("\n");
}

function memoryEventId(taskId, text) {
  const encoded = Buffer.from(text).toString("base64url").slice(0, 24);
  return `${taskId}-${encoded || "empty"}`;
}

export function createDottieExtension({
  memory,
  systemOne,
  holdAt = 0.85,
  reviewAt = 0.6,
  clock = Date.now,
} = {}) {
  if (!memory) throw new TypeError("memory is required");
  if (!systemOne) throw new TypeError("systemOne is required");

  return defineExtension({
    name: "dottie-body",
    hooks: [
      hook(GenerationTask, {
        beforeRequest: async ({ messages }, api, context) => {
          const query = extractLatestUserText(messages);
          if (!query) return undefined;

          let recall = await api.memo("dottie:memory-recall", context);
          if (recall === undefined) {
            try {
              recall = await memory.recall(query);
              recall = await api.memo("dottie:memory-recall", recall, context);
            } catch {
              return undefined;
            }
          }

          const injected = memorySystemMessage(recall, clock());
          return injected
            ? { messages: injectBeforeLatestUser(messages, injected) }
            : undefined;
        },

        afterResponse: async (message, api) => {
          const text = messageText(message).trim();
          if (!text) return;
          const observedAt = clock();
          const id = memoryEventId(api.taskId, text);
          try {
            await memory.commitEvent({
              id,
              markdown: eventMarkdown(message, api.taskId, observedAt),
              tags: ["source=pi-durable"],
            });
          } catch {
            // Pi remains the durable body if long-term memory is temporarily unavailable.
          }
        },
      }),

      hook(ToolTask, {
        beforeTool: async (call, api, context) => {
          let judgment = await api.memo("dottie:system-one", context);
          if (judgment === undefined) {
            try {
              const candidate = await systemOne.judge(
                reflexStateForTool(call),
                reflexQuestionsForTool(call),
                { signal: context.abortSignal },
              );
              judgment = await api.memo("dottie:system-one", candidate, context);
            } catch {
              return undefined;
            }
          }

          const disposition = reflexDisposition(judgment.answers, { holdAt, reviewAt });
          if (disposition.action === "hold") {
            return {
              block: `Dottie reflex hold: ${disposition.reason}=${disposition.probability.toFixed(2)}`,
            };
          }
          if (disposition.action === "review") {
            return {
              block: `Dottie reflex review: ${disposition.reason}=${disposition.probability.toFixed(2)}; reconsider or establish state before retrying.`,
            };
          }
          return undefined;
        },
      }),
    ],
  });
}
