{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/The_Workshop_Mk1","path":"DOTTIE_BODY/src/runtime.mjs","content":"import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import {
  AssistantEntry,
  Harness,
  createRegistry,
  defineDoc,
} from "@earendil-works/pi-durable";
import { openNodeSqliteStorage } from "@earendil-works/pi-durable/storage/sqlite/node";
import { OpenVikingHttpClient } from "./openviking-client.mjs";
import { deterministicRequestId } from "./core.mjs";
import { LayaClient } from "./laya-client.mjs";
import { DottieMemory } from "./memory.mjs";
import { createDottieExtension } from "./pi-extension.mjs";

export const DeliveryReceipts = defineDoc({
  checkpointWhen: () => false,
  kind: "gmri.dottie.delivery-receipts",
  version: 1,
  scope: "conversation",
  history: "rewindable",
  fork: "asOf",
  initial: () => ({ deliveredSubmissionIds: [] }),
});

async function commitAnswerExactlyOnce({ harness, root, submission, settled, context }) {
  if (settled.status !== "done" || settled.type !== "input") return undefined;
  const key = String(submission.id);
  const existing = await harness.snapshot(DeliveryReceipts, root.id, context);
  if (existing?.deliveredSubmissionIds?.includes(key)) return undefined;

  return root.commit(async (tx) => {
    const receipts = await tx.doc(DeliveryReceipts, root.id);
    if (receipts.deliveredSubmissionIds.includes(key)) return undefined;
    const entry = tx.entry(AssistantEntry, settled.answer);
    receipts.deliveredSubmissionIds.push(key);
    return entry;
  }, context);
}

export async function openDottieRuntime({
  models,
  model,
  storagePath = "./dottie.sqlite",
  openVikingClient,
  openViking = {},
  systemOne,
  laya = {},
  extensions = [],
  settings,
  env,
  onReport,
  context = BACKGROUND_CONTEXT,
  clock = Date.now,
} = {}) {
  if (!models) throw new TypeError("models is required");
  if (!model?.provider || !model?.modelId) throw new TypeError("model {provider, modelId} is required");

  const ov =
    openVikingClient ??
    new OpenVikingHttpClient({
      baseUrl: openViking.baseUrl ?? process.env.OPENVIKING_URL ?? "http://127.0.0.1:1933",
      apiKey: openViking.apiKey ?? process.env.OPENVIKING_API_KEY,
      account: openViking.account ?? process.env.OPENVIKING_ACCOUNT,
      user: openViking.user ?? process.env.OPENVIKING_USER ?? "dottie",
    });

  const memory = new DottieMemory({
    client: ov,
    sessionId: openViking.sessionId ?? "dottie",
    memoryRoot: openViking.memoryRoot ?? "viking://~/memories",
    recallTokens: openViking.recallTokens ?? 3500,
  });

  const reflex =
    systemOne ??
    new LayaClient({
      baseUrl: laya.baseUrl ?? process.env.LAYA_BASE_URL ?? "http://127.0.0.1:3777",
      systemOneUrl: laya.systemOneUrl ?? process.env.LAYA_SYSTEMONE_URL,
      apiKey: laya.apiKey ?? process.env.LAYA_SYSTEMONE_API_KEY,
      timeoutMs: laya.timeoutMs ?? 15_000,
    });

  const body = createDottieExtension({
    memory,
    systemOne: reflex,
    holdAt: laya.holdAt ?? 0.85,
    reviewAt: laya.reviewAt ?? 0.6,
    clock,
  });

  const registry = createRegistry();
  for (const extension of extensions) registry.install(extension);
  registry.install(body);

  const storage = await openNodeSqliteStorage(storagePath);
  const harness = await Harness.open(
    storage,
    { models, registry, settings, env, onReport },
    context,
  );
  const root = await harness.root(context, { agent: { model } });
  harness.resume();

  return {
    harness,
    root,
    memory,
    systemOne: reflex,
    body,

    async submit(content, {
      sourceId = "operator",
      requestId = deterministicRequestId(sourceId, typeof content === "string" ? content : JSON.stringify(content)),
      whenBusy = "steer",
    } = {}) {
      const submission = await root.submit({ type: "input", content, requestId, whenBusy }, context);
      const settled = await submission.wait(context);
      const entry = await commitAnswerExactlyOnce({ harness, root, submission, settled, context });
      return { submission, settled, entry };
    },

    inspect() {
      return harness.inspect(context);
    },


    resume() {
      harness.resume();
    },

    close() {
      return harness.close(context);
    },
  };
}
