test('deterministic request ids are stable and content-sensitive', () => {
  const a = deterministicRequestId('ios:42', 'hello');
  const b = deterministicRequestId('ios:42', 'hello');
  const c = deterministicRequestId('ios:42', 'goodbye');
  assert.equal(a, b);
  assert.notEqual(a, c);
  assert.match(a, /^dottie:[0-9a-f]{32}$/);
});

test('latest user text is recovered from multimodal content', () => {
  const messages = [
    { role: 'user', content: 'old' },
    { role: 'assistant', content: 'answer' },
    { role: 'user', content: [{ type: 'text', text: 'new' }, { type: 'image', data: 'x' }] },
  ];
  assert.equal(extractLatestUserText(messages), 'new');
});

test('reflex disposition holds, reviews, or continues by calibrated threshold', () => {
  assert.deepEqual(reflexDisposition({ x: { noul: 0.91 } }), { action: 'hold', reason: 'x', probability: 0.91 });
  assert.deepEqual(reflexDisposition({ x: { noul: 0.72 } }), { action: 'review', reason: 'x', probability: 0.72 });
  assert.deepEqual(reflexDisposition({ x: { noul: 0.22 } }), { action: 'continue', reason: null, probability: 0.22 });
});

test('tool reflex payload stays bounded to typed questions and current call state', () => {
  const call = { name: 'bash', arguments: { command: 'rm -rf build' }, parent: { callId: 'p' } };
  const questions = reflexQuestionsForTool(call);
  assert.deepEqual(Object.keys(questions), ['irreversible', 'authority', 'ambiguity']);
  assert.match(reflexStateForTool(call), /rm -rf build/);
});

test('memory recall becomes a provenance-bearing system message', () => {
  const message = memorySystemMessage({ text: 'Grizz prefers receipts.', provenance: [{ uri: 'viking://x' }] }, 123);
  assert.equal(message.role, 'system');
  assert.equal(message.timestamp, 123);
  assert.match(message.content, /Grizz prefers receipts/);
  assert.match(message.content, /viking:\/\/x/);
});
