test("OpenViking client sends identity headers and context-mode search body", async () => {
  let seen;
  const client = new OpenVikingHttpClient({
    baseUrl: "http://ov.local:1933",
    apiKey: "key",
    account: "gmri",
    user: "dottie",
    fetchImpl: async (url, init) => {
      seen = { url: String(url), init };
      return new Response(JSON.stringify({
        status: "ok",
        result: { rendered: "memory", entries: [{ uri: "viking://~/memories/x.md" }] },
      }), { status: 200 });
    },
  });

  const result = await client.searchContext("continue", {
    sessionId: "dottie",
    maxTokens: 3000,
    purpose: "chat",
    includeProvenance: true,
  });

  assert.equal(seen.url, "http://ov.local:1933/api/v1/search/search");
  assert.equal(seen.init.headers.get("X-API-Key"), "key");
  assert.equal(seen.init.headers.get("X-OpenViking-Account"), "gmri");
  assert.equal(seen.init.headers.get("X-OpenViking-User"), "dottie");
  assert.deepEqual(JSON.parse(seen.init.body), {
    query: "continue",
    mode: "context",
    session_id: "dottie",
    include_provenance: true,
    max_tokens: 3000,
    purpose: "chat",
  });
  assert.equal(result.rendered, "memory");
});

test("OpenViking sessionExists maps only HTTP 404 to false", async () => {
  const client = new OpenVikingHttpClient({
    fetchImpl: async () => new Response(JSON.stringify({
      status: "error",
      error: { code: "NOT_FOUND", message: "missing" },
    }), { status: 404 }),
  });
  assert.equal(await client.sessionExists("dottie"), false);
});

test("OpenViking content write and read consume response envelopes", async () => {
  const calls = [];
  const client = new OpenVikingHttpClient({
    fetchImpl: async (url, init) => {
      calls.push({ url: String(url), init });
      if (init.method === "POST") {
        return new Response(JSON.stringify({ status: "ok", result: { uri: "viking://~/memories/x.md" } }));
      }
      return new Response(JSON.stringify({ status: "ok", result: "# memory" }));
    },
  });
  await client.write("viking://~/memories/x.md", "# memory", { wait: true });
  const readback = await client.read("viking://~/memories/x.md", 0, -1);
  assert.equal(readback, "# memory");
  assert.equal(JSON.parse(calls[0].init.body).wait, true);
  assert.match(calls[1].url, /api\/v1\/content\/read/);
});

test("OpenViking createSession preserves explicit null auto-commit policy", async () => {
  let body;
  const client = new OpenVikingHttpClient({
    fetchImpl: async (_url, init) => {
      body = JSON.parse(init.body);
      return new Response(JSON.stringify({ status: "ok", result: { session_id: "dottie" } }));
    },
  });
  await client.createSession({ sessionId: "dottie", autoCommitPolicy: null });
  assert.deepEqual(body, { session_id: "dottie", auto_commit_policy: null });
});
