{"path":"/GitHub/link_6aacf81066c081918b61766cfb3f9d27/create_file","args":{"repository_full_name":"oldmangrizzz/The_Workshop_Mk1","path":"DOTTIE_BODY/test/runtime.test.mjs","content":"import test from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import { createModels } from "@earendil-works/pi-ai/models";
import { fauxAssistantMessage, fauxProvider } from "@earendil-works/pi-ai/providers/faux";
import { openDottieRuntime } from "../src/runtime.mjs";

function fakeOpenViking() {
  const files = new Map();
  return {
    files,
    sessions: new Set(),
    async sessionExists(id) { return this.sessions.has(id); },
    async createSession({ sessionId }) { this.sessions.add(sessionId); return { session_id: sessionId }; },
    async searchContext() { return { context: "persistent Dottie memory", provenance: [{ uri: "viking://memory/1" }] }; },
    async write(uri, content) { files.set(uri, content); return {}; },
    async read(uri) { return files.get(uri); },
  };
}

function quietSystemOne() {
  return {
    async judge() {
      return {
        answers: {
          irreversible: { noul: 0.1 },
          authority: { noul: 0.1 },
          ambiguity: { noul: 0.1 },
        },
        model: "laya/test",
      };
    },
  };
}

function fauxModels(responses = []) {
  const faux = fauxProvider();
  const models = createModels();
  models.setProvider(faux.provider);
  faux.setResponses(responses);
  return { faux, models };
}

test("Dottie submission is durable and assistant delivery is exactly once", async () => {
  const directory = await mkdtemp(join(tmpdir(), "dottie-body-"));
  const storagePath = join(directory, "dottie.sqlite");
  const { models } = fauxModels([fauxAssistantMessage("I am here.")]);
  const runtime = await openDottieRuntime({
    models,
    model: { provider: "faux", modelId: "faux-1" },
    storagePath,
    openVikingClient: fakeOpenViking(),
    systemOne: quietSystemOne(),
  });
  try {
    const first = await runtime.submit("hello", { sourceId: "operator:1" });
    const duplicate = await runtime.submit("hello", { sourceId: "operator:1" });
    assert.equal(first.submission.id, duplicate.submission.id);

    const page = await runtime.root.entries({}, 100, undefined, BACKGROUND_CONTEXT);
    assert.equal(page.items.filter((entry) => entry.kind === "pi.assistant").length, 1);
  } finally {
    await runtime.close();
    await rm(directory, { recursive: true, force: true });
  }
});

test("Dottie reopens the same Pi body without replaying an acknowledged input", async () => {
  const directory = await mkdtemp(join(tmpdir(), "dottie-reopen-"));
  const storagePath = join(directory, "dottie.sqlite");
  const memory = fakeOpenViking();

  const firstModels = fauxModels([fauxAssistantMessage("survived")]).models;
  const first = await openDottieRuntime({
    models: firstModels,
    model: { provider: "faux", modelId: "faux-1" },
    storagePath,
    openVikingClient: memory,
    systemOne: quietSystemOne(),
  });
  const original = await first.submit("persist this", { sourceId: "operator:2" });
  await first.close();

  const secondModels = fauxModels([]).models;
  const reopened = await openDottieRuntime({
    models: secondModels,
    model: { provider: "faux", modelId: "faux-1" },
    storagePath,
    openVikingClient: memory,
    systemOne: quietSystemOne(),
  });
  try {
    const repeated = await reopened.submit("persist this", { sourceId: "operator:2" });
    assert.equal(repeated.submission.id, original.submission.id);
    const page = await reopened.root.entries({}, 100, undefined, BACKGROUND_CONTEXT);
    assert.equal(page.items.filter((entry) => entry.kind === "pi.assistant").length, 1);
  } finally {
    await reopened.close();
    await rm(directory, { recursive: true, force: true });
  }
});
